    "19-02_ROC_Shapes_AUC_and_Comparing_Models": [
      {
        caption: "Slide 5: ideal ROC (AUC = 1), random-guess diagonal (AUC = 0.5) and a typical good model (0.5 < AUC < 1). Shaded area = AUC.",
        svg: (function(){
          var panel = function(ox, title, sub, areaPath, linePath, extra){
            return '<g transform="translate(' + ox + ',24)">' +
              '<line x1="30" y1="140" x2="170" y2="140" stroke="var(--border)" stroke-width="2"/>' +
              '<line x1="30" y1="140" x2="30" y2="0" stroke="var(--border)" stroke-width="2"/>' +
              '<path d="' + areaPath + '" fill="rgba(34,197,94,0.25)" stroke="none"/>' +
              '<line x1="30" y1="140" x2="170" y2="0" stroke="var(--text-faint)" stroke-width="1.2" stroke-dasharray="4 4"/>' +
              '<path d="' + linePath + '" fill="none" stroke="var(--accent)" stroke-width="2.6" stroke-linejoin="round"/>' +
              '<text x="100" y="158" text-anchor="middle" font-size="11.5" fill="var(--text-muted)">FPR</text>' +
              '<text x="12" y="72" text-anchor="middle" font-size="11.5" fill="var(--text-muted)" transform="rotate(-90 12 72)">TPR</text>' +
              (extra || '') +
              '<text x="100" y="180" text-anchor="middle" font-size="13" font-weight="600" fill="var(--text)">' + title + '</text>' +
              '<text x="100" y="196" text-anchor="middle" font-size="12" fill="var(--text-muted)">' + sub + '</text></g>';
          };
          return '<svg viewBox="0 0 560 240" role="img" aria-label="Three ROC curves: ideal, random and typical, with the area under each shaded">' +
            panel(0, 'Ideal', 'AUC = 1', 'M30,140 L30,0 L170,0 L170,140 Z', 'M30,140 L30,0 L170,0') +
            panel(186, 'Random guessing', 'AUC = 0.5', 'M30,140 L170,140 L170,0 Z', 'M30,140 L170,0') +
            panel(372, 'Typical good model', '0.5 &lt; AUC &lt; 1', 'M30,140 C34,50 70,14 170,0 L170,140 Z', 'M30,140 C34,50 70,14 170,0') +
          '</svg>';
        })()
      }
    ],

    // Lecture 19, Topic 04 — Worked Example 1
    // Plots the slide-13 ROC step curve (AUC = 0.76) with the random-guess diagonal.
    "19-04_Worked_Example_1_Building_a_ROC_Curve_and_AUC": [
      {
        caption: "Example 1 (slides 12–13): ROC staircase built from the 10 ranked tuples (P moves up 0.2, N moves right 0.2). Shaded area = AUC = 0.76; dashed diagonal = random guessing.",
        svg: (function(){
          var pts = [[0,0],[0,.2],[0,.4],[.2,.4],[.2,.6],[.2,.8],[.4,.8],[.6,.8],[.8,.8],[.8,1],[1,1]];
          var X = function(v){ return 60 + v * 300; }, Y = function(v){ return 270 - v * 240; };
          var d = '', area = 'M' + X(0) + ',' + Y(0) + ' ', i;
          for (i = 0; i < pts.length; i++) { d += (i ? 'L' : 'M') + X(pts[i][0]) + ',' + Y(pts[i][1]) + ' '; area += 'L' + X(pts[i][0]) + ',' + Y(pts[i][1]) + ' '; }
          area += 'L' + X(1) + ',' + Y(0) + ' Z';
          var out = '<svg viewBox="0 0 440 320" role="img" aria-label="ROC staircase for example 1 with AUC 0.76">' +
            '<path d="' + area + '" fill="rgba(34,197,94,0.25)"/>' +
            '<line x1="' + X(0) + '" y1="' + Y(0) + '" x2="' + X(1) + '" y2="' + Y(1) + '" stroke="var(--text-faint)" stroke-width="1.5" stroke-dasharray="5 5"/>' +
            '<line x1="' + X(0) + '" y1="' + Y(0) + '" x2="' + X(1) + '" y2="' + Y(0) + '" stroke="var(--border)" stroke-width="2"/>' +
            '<line x1="' + X(0) + '" y1="' + Y(0) + '" x2="' + X(0) + '" y2="' + Y(1) + '" stroke="var(--border)" stroke-width="2"/>' +
            '<path d="' + d + '" fill="none" stroke="var(--accent)" stroke-width="2.6" stroke-linejoin="round"/>';
          for (i = 0; i < pts.length; i++) out += '<circle cx="' + X(pts[i][0]) + '" cy="' + Y(pts[i][1]) + '" r="3.8" fill="var(--accent)"/>';
          for (var v = 0; v <= 5; v++) {
            out += '<text x="' + X(v / 5) + '" y="' + (Y(0) + 16) + '" text-anchor="middle" font-size="11.5" fill="var(--text-faint)">' + (v / 5).toFixed(1) + '</text>' +
                   '<text x="' + (X(0) - 8) + '" y="' + (Y(v / 5) + 4) + '" text-anchor="end" font-size="11.5" fill="var(--text-faint)">' + (v / 5).toFixed(1) + '</text>';
          }
          out += '<text x="' + X(.5) + '" y="' + (Y(0) + 36) + '" text-anchor="middle" font-size="13" fill="var(--text)">False positive rate (FPR)</text>' +
                 '<text x="16" y="' + Y(.5) + '" text-anchor="middle" font-size="13" fill="var(--text)" transform="rotate(-90 16 ' + Y(.5) + ')">True positive rate (TPR)</text>' +
                 '<text x="' + X(.62) + '" y="' + Y(.35) + '" text-anchor="middle" font-size="14" font-weight="700" fill="var(--text)">AUC = 0.76</text>' +
                 '<text x="' + X(.78) + '" y="' + Y(.62) + '" font-size="11.5" fill="var(--text-muted)">random guessing</text></svg>';
          return out;
        })()
      }
    ],

